```c++
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Replace all HTML tags with their corresponding HTML entities
    std::string html = boost::algorithm::replace_all(markdown, "<", "&lt;");
    html = boost::algorithm::replace_all(html, ">", "&gt;");
    html = boost::algorithm::replace_all(html, "&", "&amp;");
    html = boost::algorithm::replace_all(html, "\"", "&quot;");
    html = boost::algorithm::replace_all(html, "\'", "&apos;");
    html = boost::algorithm::replace_all(html, "\n", "&nbsp;");

    return html;
}

int main() {
    std::string markdown = "```Markdown\nThis is a simple example of markdown formatting.\n```";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses the Boost library to replace all HTML tags with their corresponding HTML entities. It then uses the `replace_all` function from Boost to replace all newline characters with HTML line breaks (`&nbsp;`). Finally, it returns the resulting HTML string.

